CREATE TABLE IF NOT EXISTS member(member_id VARCHAR(10) PRIMARY KEY,full_name VARCHAR(80) NOT NULL,phone VARCHAR(20),village VARCHAR(60),no_of_cows INT DEFAULT 0,join_date DATE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_account(user_id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(30) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL,full_name VARCHAR(80),member_id VARCHAR(10) NULL,FOREIGN KEY(member_id) REFERENCES member(member_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS delivery(delivery_id INT AUTO_INCREMENT PRIMARY KEY,member_id VARCHAR(10) NOT NULL,recorded_by INT NOT NULL,delivery_date DATE NOT NULL,delivery_time VARCHAR(8),litres DECIMAL(8,1) NOT NULL,FOREIGN KEY(member_id) REFERENCES member(member_id),FOREIGN KEY(recorded_by) REFERENCES user_account(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS quality_test(test_id INT AUTO_INCREMENT PRIMARY KEY,delivery_id INT UNIQUE NOT NULL,tested_by INT NOT NULL,fat_percent DECIMAL(3,1),temperature DECIMAL(4,1),adulterated TINYINT(1) DEFAULT 0,result VARCHAR(10),grade VARCHAR(2),FOREIGN KEY(delivery_id) REFERENCES delivery(delivery_id),FOREIGN KEY(tested_by) REFERENCES user_account(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payment(payment_id INT AUTO_INCREMENT PRIMARY KEY,member_id VARCHAR(10) NOT NULL,paid_by INT NOT NULL,pay_month CHAR(7) NOT NULL,gross_amount DECIMAL(12,0),deductions DECIMAL(12,0),net_amount DECIMAL(12,0),paid_date DATE,UNIQUE(member_id,pay_month),FOREIGN KEY(member_id) REFERENCES member(member_id),FOREIGN KEY(paid_by) REFERENCES user_account(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS buyer(buyer_id INT AUTO_INCREMENT PRIMARY KEY,buyer_name VARCHAR(80) NOT NULL,phone VARCHAR(20),buyer_type VARCHAR(30)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS milk_sale(sale_id INT AUTO_INCREMENT PRIMARY KEY,buyer_id INT NOT NULL,sale_date DATE,litres DECIMAL(8,1),price_per_litre DECIMAL(8,0),FOREIGN KEY(buyer_id) REFERENCES buyer(buyer_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stock_item(item_id INT AUTO_INCREMENT PRIMARY KEY,item_name VARCHAR(80),category VARCHAR(20),quantity INT,reorder_level INT,unit_price DECIMAL(10,0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stock_issue(issue_id INT AUTO_INCREMENT PRIMARY KEY,member_id VARCHAR(10) NOT NULL,item_id INT NOT NULL,quantity INT,on_credit TINYINT(1) DEFAULT 1,issue_date DATE,amount DECIMAL(12,0),FOREIGN KEY(member_id) REFERENCES member(member_id),FOREIGN KEY(item_id) REFERENCES stock_item(item_id)) ENGINE=InnoDB;
